const results = [];
for (const item of $input.all()) {
  const raw = item.json.output[0].content[0].text;
  const clean = raw.replace(/```json/gi, '').replace(/```/g, '').trim();
  let d;
  try {
    d = JSON.parse(clean);
  } catch (e) {
    d = { observacoes: 'JSON inválido: ' + raw.slice(0, 200) };
  }
  const form = $('On form submission').first().json;
  const lista = (v) => Array.isArray(v) ? v.join('\n') : (v ?? '');
  const aderencia = Array.isArray(d.aderencia)
    ? d.aderencia.map(a => `${a.requisito}: ${a.status} (${a.justificativa ?? ''})`).join('\n')
    : (d.aderencia ?? '');
  const riscos = Array.isArray(d.riscos)
    ? d.riscos.map(r => typeof r === 'string' ? r : `${r.risco} [trecho: "${r.trecho_da_vaga ?? ''}"]`).join('\n')
    : (d.riscos ?? '');
  results.push({ json: {
    data: new Date().toLocaleDateString('pt-BR'),
    empresa: d.empresa ?? '',
    cargo: d.cargo ?? '',
    resumo: d.resumo ?? '',
    requisitos: lista(d.requisitos),
    aderencia,
    riscos,
    observacoes: d.observacoes ?? '',
    link: form['Link da vaga'] ?? '',
    local_modelo: d.local_modelo ?? '',
    diferenciais: lista(d.diferenciais)
  }});
}
return results;
